 uint8_t encrypted[16]; mbedtls_aes_context aes; mbedtls_aes_init(&aes);
 mbedtls_aes_setkey_enc(&aes,key,128); mbedtls_aes_crypt_ecb(&aes,MBEDTLS_AES_ENCRYPT,b+1,encrypted); mbedtls_aes_free(&aes);
